function ringSlope(radius: number, focal: number): number {
  // The surface must turn light toward the focal point.
  const angle = Math.atan(radius / focal);
  return Math.tan(angle / 2); // thin-lens approximation
}

const slopes = [0.1, 0.2, 0.3].map((r) => ringSlope(r, 0.92));
console.log("ring slopes:", slopes);
